window.ScripturaLexicons.DGP.cardsHtml += "<article id=\"entry-dgp-25301\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λιχνεία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 694 na letra λ · nº geral 25301</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 gulodice 2 iguaria delicada; guloseima. 〈λιχνεύω〉</p></section></article>\n<article id=\"entry-dgp-25302\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λιχνεύω</h1><div class=\"entry-meta\"><span>DGP · ordem 695 na letra λ · nº geral 25302</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. λιχνεύσω) 1 lamber ♦ at. e méd. 2 estar ávido de; cobiçar, ac., εἰς ou περί e ac., ou inf. 〈λίχνος〉</p></section></article>\n<article id=\"entry-dgp-25303\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λίχνος, η,</h1><div class=\"entry-meta\"><span>DGP · ordem 696 na letra λ · nº geral 25303</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">poét. ος, ον 1 apreciador de boa mesa; guloso 2 que cobiça; ávido 3 curioso 4 apetitoso (alimento).</p></section></article>\n<article id=\"entry-dgp-25304\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λίψ1, λιβός (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 697 na letra λ · nº geral 25304</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">vento do sudoeste, lit. “o chuvoso”.</p></section></article>\n<article id=\"entry-dgp-25305\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λίψ2, λιβός</h1><div class=\"entry-meta\"><span>DGP · ordem 698 na letra λ · nº geral 25305</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">só gen. e ac. λίβα (ἡ) 1 rocha de onde goteja água 2 gota 3 lágrima 4 libação.</p></section></article>\n<article id=\"entry-dgp-25306\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λιψουρία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 699 na letra λ · nº geral 25306</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">necessidade de urinar. 〈λίπτω, οὐρέω〉</p></section></article>\n<article id=\"entry-dgp-25307\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λοβός, οῦ (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 700 na letra λ · nº geral 25307</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 lóbulo 2 lóbulo do fígado 3 fígado 4 ponta da orelha 5 extremidade inferior de uma folha de rosa 6 casca; vagem.</p></section></article>\n<article id=\"entry-dgp-25308\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λογάδην</h1><div class=\"entry-meta\"><span>DGP · ordem 701 na letra λ · nº geral 25308</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. 1 aos montes; em pilha; acumuladamente 2 com escolha. 〈λογάς, -δην〉</p></section></article>\n<article id=\"entry-dgp-25309\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λογάριον, ου (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 702 na letra λ · nº geral 25309</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 palavra breve; sentença curta 2 mau discurso. 〈λόγος〉</p></section></article>\n<article id=\"entry-dgp-25310\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λογάς, άδος</h1><div class=\"entry-meta\"><span>DGP · ordem 703 na letra λ · nº geral 25310</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(masc., fem.) 1 recolhido: λογάδες λίθοι paus. pedras recolhidas para construção 2 de escol; de elite; seleto: λογάσι νεανίαις eur. jovens de escol 3 eloqüente ♦ οἱ λογάδες [στρατιῶται, ἄνδρες] 4 soldados de elite; tropa de elite. 〈λέγω1〉</p></section></article>\n<article id=\"entry-dgp-25311\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λογάω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 704 na letra λ · nº geral 25311</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(só pres.) ter vontade de falar. 〈λόγος〉</p></section></article>\n<article id=\"entry-dgp-25312\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λογεία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 705 na letra λ · nº geral 25312</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">tard. 1 recolhimento; arrecadação 2 bíbl. coleta. 〈λογεύς〉</p></section></article>\n<article id=\"entry-dgp-25313\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λογεῖον, ου (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 706 na letra λ · nº geral 25313</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 Dram. parte da cena onde os atores atuavam 2 tribunal 3 peitoral do sumo sacerdote judeu. 〈λόγος〉</p></section></article>\n<article id=\"entry-dgp-25314\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λογεύς, έως (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 707 na letra λ · nº geral 25314</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">orador. 〈λόγος〉</p></section></article>\n<article id=\"entry-dgp-25315\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λογίδιον, ου (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 708 na letra λ · nº geral 25315</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 discurso breve; conversa rápida 2 narrativa curta. 〈λόγος〉</p></section></article>\n<article id=\"entry-dgp-25316\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λογίζομαι</h1><div class=\"entry-meta\"><span>DGP · ordem 709 na letra λ · nº geral 25316</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. λογίσομαι, át. λογιοῦμαι, aor. ἐλογισάμην, perf. λελόγισμαι; pas. aor. ἐλογίσθην, perf. λελόγισμαι) 1 avaliar; calcular; contar: λ. τοὺς τόκους ar. calcular os juros, λ. μὴ ψήφοισι ἀλλ’ ἀπὸ χειρός calcular não com seixos mas com os dedos, τὰς βλάβας ἃς ἐλογίζετο αὐτῷ γεγε­νῆσθαι dem. os prejuízos que avaliava lhe terem sucedido, πεντακισχίλια καὶ μυρία λογίζονται εἶναι [τὰ ἔτεα] her. calculam que são 15.000 anos 2 incluir numa conta; contar no número de: τὸν Πᾶνα τῶν ὀκτὼ θεῶν λογίζονται εἶναι her. contar Pã no número dos oito deuses 3 lançar algo, ac., na conta de alguém, dat.; debitar: λ. δώδεκα μνᾶς ar. lançar na conta doze minas 4 pôr na conta de; imputar ou atribuir algo, ac., a alguém, dat.: τὸ ἥμισυ τούτοις ὀρφανοῖς οὖσι λελόγισται lís. atribuiu a esses, que são órfãos, metade do valor [de 48 minas] 5 verificar as contas de alguém, dat.: κληροῦσι δὲ καὶ λογιστὰς δέκα τοὺς λογιουμένους ταῖς ἀρχαῖς κατὰ τὴν πρυτανείαν ἑκάστην artt. sorteiam também dez auditores, para verificar as contas dos oficiais de cada pritania 6 considerar; meditar; pensar algo, ac., or. inf., part. ou conj. (ὅτι, ὡς): ἐκ τούτων τῶν λόγων τοιόνδε τι λογίζομαι συμβαίνειν plat. desses argumentos penso que deriva uma tal conclusão, Σμέρδιν οὐκ ἔτι ἐόντα λογίζεσθε her. considerai que Esmérdis não vive mais, ἐλογιζόμην ὅτι τούτου μὲν τοῦ ἀνθρώπου σοφώτερός εἰμι plat. eu pensava que do que esse homem eu era mais sábio 7 contar; fazer previsão ou suposição de; esperar algo, ac., or. inf.: δύο ἢ κἀπὶ πλείους ἡμέρας λογίζεται sóf. faz previsão de dois ou mais dias, λογιζόμενοι ἥξειν ἅμα ἡλίῳ δύνοντι xen. contando em chegar ao pôr do sol 8 concluir; deduzir; inferir: ὅτι τὴν ὑμετέραν πόλιν δυναίμην ἂν παραστήσασθαι ἔξεστί σοι ἐκ τῶνδε λογίζεσθαι xen. a partir disso te é permitido deduzir que posso subjugar vossa cidade 9 bíbl. cogitar; tramar algo, ac., contra alguém, εἰς e ac. ♦ pas. τὸ λελογισμένον 10 o raciocínio. 〈λόγος〉</p></section></article>\n<article id=\"entry-dgp-25317\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λογικός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 710 na letra λ · nº geral 25317</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 referente à palavra: λογικὰ μέρη plut. os órgãos da palavra 2 hábil para falar; eloqüente 3 referente à declamação 4 próprio do discurso em prosa 5 que diz respeito ao raciocínio, à razão; racional (técnica) 6 conforme à razão; racional; lógico: λ. ἀπόδειξις artt. demonstração lógica, λογικοὶ συλλογισμοί artt. silogismos lógicos, op. aos retóricos 7 dotado de razão; racional 8 racional; teórico; dogmático (médico) 9 crist. espiritual: λογικὴ λατρεία n.t. culto espiritual ♦ ὁ λογικός 10 o prosador ♦ ἡ λογική 11 a ciência do raciocínio; a lógica 12 [λέξις] a prosa ♦ τὸ λογικόν 13 a racionalidade ♦ τὰ λογικά 14 as criaturas racionais. 〈λόγος〉</p></section></article>\n<article id=\"entry-dgp-25318\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λόγιμος, η, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 711 na letra λ · nº geral 25318</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">digno de menção; notável; famoso. 〈λόγος〉</p></section></article>\n<article id=\"entry-dgp-25319\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λόγιον, ου (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 712 na letra λ · nº geral 25319</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">cf. λόγιος.</p></section></article>\n<article id=\"entry-dgp-25320\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λόγιος, α, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 713 na letra λ · nº geral 25320</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 hábil no falar; diserto; eloqüente 2 que se expressa em prosa; prosador 3 hábil em raciocinar; competente; sábio; douto (médico) 4 conhecedor das lendas ou da história de um país ♦ ὁ Λόγιος 5 o deus da eloqüência, Hermes ♦ τὸ λόγιον 6 resposta do oráculo; predição 7 bíbl. profecia 8 bíbl. ensinamento; palavra divina inspirada 9 bíbl. passagem da Escritura 10 peitoral do sumo sacerdote judeu. 〈λόγος〉</p></section></article>\n<article id=\"entry-dgp-25321\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λογιότης, ητος (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 714 na letra λ · nº geral 25321</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">eloqüência. 〈λόγιος〉</p></section></article>\n<article id=\"entry-dgp-25322\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λογισμός, οῦ (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 715 na letra λ · nº geral 25322</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 cálculo numérico; conta: ἐκ λογισ­μοῦ τῶν ἡμερῶν tuc. a partir do cálculo dos dias, τυγχάνειν τοῦ ἀληθοῦς λ. tuc. fazer a conta exata, ἐν λογισμῷ ἁμαρτάνειν plat. errar na conta 2 pl. ciência dos números; aritmética: λογισμούς τε καὶ γεωμετρίαν διδάσκειν plat. ensinar aritmética e geometria 3 cálculo; raciocínio; reflexão: λογισμῷ ἐλάχιστα χρῆσθαι tuc. refletir o mínimo, λογισμῷ δοῦναί τι lís. levar algo em conta, λογισμὸν ἔχειν περί τινος plat. refletir sobre algo, ποιεῖν τι τοιῷδε λογισμῷ ὡς xen. fazer algo com tal cálculo que, καθιστάναι τινὰ εἰς λογισμόν tuc. levar alguém a esse raciocínio 4 consideração; avaliação: ὅσον ἦν ἀνθρωπίνῳ λογισμῷ δυνατόν dem. tanto quanto era possível para um cálculo humano 5 faculdade de raciocinar; razão 6 bíbl. desígnio. 〈λογίζομαι〉</p></section></article>\n<article id=\"entry-dgp-25323\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λογιστέος, α, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 716 na letra λ · nº geral 25323</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adj. verb. de λογίζομαι</p></section></article>\n<article id=\"entry-dgp-25324\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λογιστήριον, ου (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 717 na letra λ · nº geral 25324</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 sede dos auditores de contas, em Atenas 2 lugar de reunião dos filósofos 3 sede do comando militar 4 tábua de cálculo. 〈λογίζομαι〉</p></section></article>\n<article id=\"entry-dgp-25325\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λογιστής, οῦ (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 718 na letra λ · nº geral 25325</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 em Atenas, revisor ou auditor de contas 2 professor de aritmética 3 pessoa que calcula, que avalia, que reflete. 〈λογίζομαι〉</p></section></article>\n<article id=\"entry-dgp-25326\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λογιστικός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 719 na letra λ · nº geral 25326</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 que diz respeito ao cálculo 2 hábil em cálculo 3 que diz respeito ao raciocínio; conforme à razão; racional 4 que raciocina bem; razoável; sensato ♦ ἡ λογιστική 5 ciência prática do cálculo ♦ ὁ λογιστικός 6 calculador hábil ♦ τὸ λογιστικὸν 7 faculdade de raciocinar; razão. 〈λογίζομαι〉</p></section></article>\n<article id=\"entry-dgp-25327\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λογίως</h1><div class=\"entry-meta\"><span>DGP · ordem 720 na letra λ · nº geral 25327</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. com eloqüência.</p></section></article>\n<article id=\"entry-dgp-25328\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λογογραφέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 721 na letra λ · nº geral 25328</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">escrever discursos em prosa para si ou para outrem. 〈λογογράφος〉</p></section></article>\n<article id=\"entry-dgp-25329\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λογογράφος, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 722 na letra λ · nº geral 25329</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 aquele que escreve em prosa; prosador; escritor 2 logógrafo; historiador 3 autor de discursos escritos para outros. 〈λόγος, γράφω〉</p></section></article>\n<article id=\"entry-dgp-25330\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λογοειδής, ής, ές</h1><div class=\"entry-meta\"><span>DGP · ordem 723 na letra λ · nº geral 25330</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 que se assemelha à prosa; prosaico 2 eloqüente 3 semelhante à razão, à inteligência. 〈λόγος, εἶδος〉</p></section></article>\n<article id=\"entry-dgp-25331\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λογομαχέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 724 na letra λ · nº geral 25331</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">bíbl. combater verbalmente; querelar. 〈λό­γος, μάχομαι〉</p></section></article>\n<article id=\"entry-dgp-25332\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λογομαχία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 725 na letra λ · nº geral 25332</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">bíbl. combate verbal; querela.</p></section></article>\n<article id=\"entry-dgp-25333\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λογονεχόντως</h1><div class=\"entry-meta\"><span>DGP · ordem 726 na letra λ · nº geral 25333</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. com prudência ou reflexão. 〈λόγος, ἔχω〉</p></section></article>\n<article id=\"entry-dgp-25334\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λογοποιέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 727 na letra λ · nº geral 25334</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 inventar histórias, mitos 2 inventar fábulas; divulgar boatos, notícias sobre alguém, περί e gen., contra alguém, κατά e gen. 3 contar mentiras a alguém, πρός e ac. 〈λογοποιός〉</p></section></article>\n<article id=\"entry-dgp-25335\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λογοποιός, ός, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 728 na letra λ · nº geral 25335</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 prosador 2 historiador em prosa 3 compositor de discursos para outrem 4 fabulista 5 divulgador de mentiras, de notícias falsas 6 novelista. 〈λόγος, ποιέω〉</p></section></article>\n<article id=\"entry-dgp-25336\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λόγος, ου</h1><div class=\"entry-meta\"><span>DGP · ordem 729 na letra λ · nº geral 25336</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(ὁ) enunciado 1 palavra; expressão; dito; discurso 2 sentença; máxima; provérbio 3 exemplo ou hipótese 4 decisão; resolução 5 condição; pacto; trato 6 palavra empenhada; promessa 7 Lóg. proposição 8 Filos. definição ou fórmula 9 doutrina ou parte de doutrina 10 ordem; comando; mandamento 11 menção; referência 12 declaração; afirmação 13 notícia que se propaga; rumor falso ou verdadeiro que corre; λόγος ἐστι, λόγος ἔχει, λόγος φέρεται com suj. or. inf. é um rumor que, espalha-se o boato que 14 reputação; fama boa ou má 15 bíbl. palavra revelada 16 a faculdade de falar; a fala 17 a vez de falar; o direito de falar 18 conversa; colóquio; discussão; εἰς λόγον ou εἰς λόγους ἐλθεῖν, συνελθεῖν, ἀφικέσθαι ou διὰ λόγων ἰέναι, ἀφι­κέσθαι, γενέσθαι conversar ou entrar em discussão com alguém, dat. argumento, matéria, assunto, objeto, questão 19 argumento; assunto; matéria 20 tema de conversa, de estudo ou de discussão 21 argumento; tema; trama; enredo de obra literária ou artística 22 aquilo de que se fala; fato; negócio; coisa texto em prosa 23 discurso; discurso oratório; oração 24 tratado de filosofia, de moral, de medicina etc.; obra ou parte de uma obra 25 diálogo socrático 26 narrativa histórica ou parte de obra histórica 27 relato; lenda; mito 28 fábula razão, julgamento, cálculo 29 faculdade de raciocinar; raciocínio; razão; inteligência 30 razão íntima de uma coisa; fundamento; lógica; motivo 31 opinião; opinião sobre algo a acontecer, presunção, espera 32 boa opinião; estima; consideração 33 conta que se faz de alguém ou de algo, gen.; avaliação; importância 34 conta; cálculo; planejamento 35 prestação de contas 36 justificativa; explicação 37 valor; significado 38 relação; proporção; analogia 39 Relig. a Palavra ou Sabedoria de Deus 1 λόγοις μ’ ἀπατᾷς teóg. enganas-me com tuas palavras, ἐν τῷ τοῦ ∆ιὸς τοῦ ∆ωδωναίου ἱερῷ δρυὸς λόγους ἔφη­σαν μαντικοὺς πρώτους γενέσθαι plat. diziam que as palavras do carvalho do santuário de Zeus de Dodona foram as primeiras palavras proféticas, αἱμύλιοι λόγοι hom. palavras de lisonja, i.e., lisonja, ψευδεῖς λόγοι hes. mentiras, ὡς εἰπεῖν λόγῳ her., λέγειν ἑνὶ λόγῳ plat. para dizer em uma palavra, i.e., brevemente, ὡς ἁπλῷ λόγῳ ou ἁπλῷ λόγῳ ésql. em uma simples palavra, com uma simples palavra, ἔργα λόγου μέζω her. ações acima do que se poderia dizer, λόγου κρεῖσσου tuc. acima de qualquer expressão, λόγῳ μὲν… ἔργῳ δε her. pelo que é dito…, mas de fato, ἔργῳ κοὐ λόγῳ ésql. em realidade e não em palavra 2 ἥλικα γὰρ δὴ καὶ ὁ παλαιὸς λόγος τέρπειν τὸν ἥλικα plat. pois cada idade, diz o antigo provérbio, se compraz com o da mesma idade, θεοὺς τοὺς τῆς ἁλούσης πόλεος ἐκλείπειν λόγος ésql. a sentença diz que os deuses de uma cidade subjugada a abandonam 3 λόγου ἕνεκα plat., λόγου χάριν artt. por exemplo, por hipótese, por suposição 4 στρατεύονται ὦν ἐπ’ αὐτοὺς κοινῷ λόγῳ χρησάμενοι Τυρσηνοὶ καὶ Καρχηδόνιοι her. então os tirrenos e os cartagineses, de comum acordo, fazem campanha militar contra eles [os foceenses] 5 ἐπὶ δὲ λόγῳ τοιῷδε τάδε ὑπίσχομαι her. faço essas promessas sob tal condição 6 οὔκουν πέρα γ’ ἂν οὐδὲν ἢ λόγῳ φέροις sóf. pois não obterias nada além da palavra empenhada 7 λόγος ὁριστικός artt. proposição para definir, definição 8 καταφανὲς ἦν ὅτι ὁ τοῦ δικαίου λόγος εἰς τουναντίον περιειστήκει plat. era evidente que a definição do justo viera dar no seu contrário 9 τριμερῆ φασιν εἶναι τὸν κατὰ φιλοσοφίαν λόγον d.l. dizem que a doutrina filosófica é tripartida 10 ἀνθρώπους δ’ ἔστι πιθανωτέρους ποιεῖν καὶ λόγῳ xen. é possível tornar os homens mais obedientes até com palavra, πᾶσιν προφωνεῖ τόνδε ναυάρχοις λόγον ésql. a todos os capitães de navios profere esta ordem, οἱ δέκα λόγοι sept. os dez mandamentos 11 τὴν ὡραίην οὐκ ὕει λόγου ἄξιον οὐδέν her. o quanto chove na estação própria (das chuvas) não vale a pena mencionar 12 ψιλῷ δὲ λόγῳ χρησάμενος dem. limitando-se a uma simples declaração 13 Κλεισθένης λόγον ἔχει τὴν Πυθίαν ἀναπεῖσαι her. Clístenes tem fama de ter persuadido a Pítia, τὴν δὲ Θεσσαλίην λόγος ἐστὶ τὸ παλαιὸν εἶναι λίμνην her. corre um boato de que antigamente a Tessália era um lago 14 ἵνα λόγος τέ σε ἔχῃ πρὸς ἀνθρώπων ἀγαθός her. para que obtenhas boa reputação da parte dos homens, παρ’ ἡμέας περὶ σέο λόγος ἀπῖκται πολλός her. teu renome chegou até nós, λόγον ἀκούειν át. ouvir falar de si 15 λόγος κυρίου sept. palavra do Senhor, ὁ λόγος τῆς ἀληθείας, τὸ εὐαγγέλιον τῆς σωτηρίας n.t. a palavra da verdade, o evangelho da salvação 16 ἀνθρώπῳ λόγος δώρημα κάλλιστον ἐδόθη παρὰ θεοῦ filon. a fala, dom belíssimo, foi dada ao homem por Deus 17 ἐδίδοσαν οἱ Λακεδαιμόνιοι τοῖς συμμάχοις λόγον xen. os lacedemônios concederam a palavra aos aliados 18 πρὸς αὐτῶν τοίνυν, ὦ Μέλητε, τούτων τῶν θεῶν ὧν νῦν ὁ λόγος ἐστίν plat. (Ap.26b) pois bem, por esses mesmos deuses, ó Meleto, de que trata neste momento a discussão, ἂν ἐγὼ πᾶσι τυράννοισι προετίμησα ἐς λόγους ἐλθεῖν her. eu preferiria que [Sólon] conversasse com todos os tiranos, συνελέχθησαν οἱ Μῆδοι ἐς τὠυτὸ καὶ ἐδίδοσαν σφίσι λόγον her. os medos se reuniram e discutiram entre si 19 μηδένα λόγον ὑπολιπεῖν τοῖς εἰθισμένοις ἐπαινεῖν isócr. não deixar nenhum argumento aos acostumados a louvar, εἰ μὲν θαρραλέως ἐγὼ ἔχω πρὸς θάνατον ἢ μή, ἄλλος λόγος plat. se diante da morte eu estou tranqüilo ou não, é outro assunto, οὐκ ὑπολείπει αὐτὸν ὁ λόγος artt. não lhe falta matéria de discurso 20 περὶ λόγου τινὸς διαλέγεσθαι plat. conversar acerca de um tema de estudo, ἐς λόγον τινός her., πρὸς λόγον τινός ésql. aquilo de que se trata, o objeto em causa, em discussão, μετέχειν τοῦ λόγου her. participar da conversa, isto é, estar a par de 21 τῆς γὰρ Ὀδυσσείας οὐ μακρὸς ὁ λόγος ἐστίν artt. de fato, a trama da Odisséia não é extensa, οἱ μεθύοντες λόγοι εἰσὶ τῆς γραφῆς filós. os bêbados são temas da pintura 22 οἱ μὴ βουλόμενοι σεμνοῦν τὰ περὶ Κῦρον ἀλλὰ τὸν ἐόντα λέγειν λόγον her. os [persas] que não pretendem enaltecer a história de Ciro, mas apenas narrar o fato como ele é, τίς ὁ λόγος οὗτος; sept. de que se trata? 23 ἐπιτάφιος λόγος plat. oração fúnebre, δικανικὸς λόγος artt. discurso judiciário 24 ἐν τοῖς ἐκδεδομένοις λόγοις artt. nos livros publicados, ἐν τῷ πρόσθεν λόγῳ xen. no livro precedente 25 οἱ Σωκρατικοὶ λόγοι artt. os diálogos socráticos 26 βασιλέες, τῶν ἐν τοῖσι Ἀσσυρίοισι λόγοισι μνήμην ποιήσομαι her. soberanos, de que irei ocupar-me em meu livro sobre os assírios 27 ὅτευ δὲ εἵνεκα φῶς ἔλαχε καὶ τιμὴν ἡ νὺξ αὕτη, ἔστι ἱρὸς περὶ αὐτοῦ λόγος λεγόμενος her. o motivo pelo qual a essa noite coube essa iluminação e essa honra, é uma lenda sagrada que se conta a seu respeito 28 Κῦρος μὲν τοῦτον τὸν λόγον τοῖσι Ἴωσι καὶ τοῖσι Αἰολεῦσι τῶνδε εἵνεκα ἔλεξε her. eis por que Ciro contou essa fábula aos jônios e aos eólios 29 ἃ μάλιστά τις ἂν λόγῳ λάβοι plat. principalmente as coisas que se pode apreender pela razão, αἳ μὲν [ἐπιθυμίαι] ἂν τῇ ἐπιστήμῃ καὶ λόγῳ ἑπόμεναι plat. os desejos que seguem a ciência e a razão, ὀρθὸς λόγος plat. a reta razão; ἔχειν λόγον plat. estar conforme a razão, ser justo ou razoável, οὐκ ἔχειν λόγον não haver razão, τὸ παρὰ λόγον (cf. παράλογος) át. o que é contrário à razão, λόγος αἰτεῖ com or. inf. a razão exige que 30 τὸν δὲ δὴ ποταμὸν τοῦτον τὸν παραρρέοντα καὶ Ἐτέαρχος συνεβάλλετο εἶναι Νεῖλον, καὶ δὴ καὶ ὁ λόγος οὕτω αἱρέει her. e esse rio que corre junto [à cidade] também Etéarco supunha que era o Nilo e, além do mais, é o que a lógica impõe, τί δή ποθ’ ὧδ’ ἐξ οὐδενὸς λόγου σιωπᾷς; sóf. por que te calas assim sem razão nenhuma? ἐκ τίνος λόγου; ésql. por que razão? 31 ἔδει δὲ μηδὲ πυρφόρον τῷ ἐκείνων λόγῳ ἐκφυγόντα περιγενέσθαι her. mas, pela opinião deles [os persas], nem o portador-do-fogo devia fugir e sobreviver, ἅπαντα νικᾶν λόγον sóf. ultrapassar tudo o que se pode dizer ou pensar, ἐπὶ τῷ λόγῳ ὥστε her. na expectativa de que 32 λόγῳ ἐν σμικρῷ εἶναι plat. gozar de medíocre estima, πλείστου λόγου εἶναι her. gozar de máxima estima, ἐλαχίστου λόγου εἶναι gozar de mínima consideração, λόγου εἶναι πρός τινος her. ser estimado por alguém, λόγου οὐδενὸς γενέσθαι πρός τινος her. não gozar de nenhuma consideração da parte de alguém, λόγον ἔχειν τινός her. estimar alguém ou alguma coisa, λόγον τινὸς οὐκ ἔχειν οὐδένα ésql. οὐδένα λόγον ποιεῖσθαί τινος her. não estimar alguém 33 Μαρδονίου δέ, ἤν τι πάθῃ, λόγος οὐδεὶς γίνεται her. Mardônio, se sofrer algum revés, não faz diferença, ἐν ἀνδρὸς λόγῳ εἶναι her. ser considerado um dentre os homens de alta linhagem, ἐν ἀνδραπόδων λόγῳ ποιεύμενος her. considerado ou tratado como escravos 34 κατὰ τύχην, οὐ σὺν λόγῳ fílon ao acaso, não por cálculo 35 ἀλλὰ μᾶλλον ὅκως λόγον δώσεις τῶν μετεχείρι­σας χρημάτων her. mas de preferência prestarás contas das riquezas que administraste, ἠθέλησεν συνᾶραι λόγον μετὰ τῶν δού­λων αὐτοῦ n.t. [o rei] quis ajustar contas com os seus escravos 36 λόγον ἑαυτῷ διδόναι περί τινος her. apreciar alguma coisa, αἰτεῖν ou ἀπαιτεῖν περί τινος át. pedir explicação a alguém, fazer-se compreender por alguém, λόγον διδόναι τινός át. ou παρέχειν plat. explicar, dar conta de alguma coisa, ἐπεὶ ὦν δὴ ἐξηγέρθη, ὁ Κῦρος ἐδίδου λόγον ἑαυτῷ περὶ ὄψιος her. depois que acordou, Ciro tentava encontrar uma explicação para seu sonho 37 τίν’ ἔχει λόγον τὸ εἰρημένον; fílon que significado tem o que foi dito? 38 ἀνὰ τὸν αὐτὸν λόγον plat., κατὰ τὸν αὐτὸν λόγον her. segundo a mesma avaliação, na mesma proporção, πρὸς λόγον τινός ésql. em consideração a, relativamente a, proporcionalmente a alguma coisa, κατὰ λόγον τῆς δυνάμεως xen. em razão de seu poder 39 ἐν ἀρχῇ ἦν ὁ λόγος n.t. no princípio era o Verbo. 〈λέγω2〉</p></section></article>\n<article id=\"entry-dgp-25337\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λόγχη, ης (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 730 na letra λ · nº geral 25337</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 ponta de lança ou de dardo; lâmina 2 lança; dardo como insígnia de comando 3 espada; punhal 4 pl. armas 5 tropa de lanceiros.</p></section></article>\n<article id=\"entry-dgp-25338\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λογχήρης, ης, ες</h1><div class=\"entry-meta\"><span>DGP · ordem 731 na letra λ · nº geral 25338</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">armado de lança. 〈λόγχη〉</p></section></article>\n<article id=\"entry-dgp-25339\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λόγχιμος, η, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 732 na letra λ · nº geral 25339</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">de lança. 〈λόγχη〉</p></section></article>\n<article id=\"entry-dgp-25340\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λογχοφόρος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 733 na letra λ · nº geral 25340</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 portador ou armado de lança ♦ ὁ λογχοφόρος 2 lanceiro. 〈λόγχη, φέρω〉</p></section></article>\n<article id=\"entry-dgp-25341\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λόε</h1><div class=\"entry-meta\"><span>DGP · ordem 734 na letra λ · nº geral 25341</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">cf. λόω.</p></section></article>\n<article id=\"entry-dgp-25342\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λόεον, λοέσσαι, λοεσσάμενος, λοέσσας, λοέσσατο, λοέσσομαι</h1><div class=\"entry-meta\"><span>DGP · ordem 735 na letra λ · nº geral 25342</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">cf. λοέω.</p></section></article>\n<article id=\"entry-dgp-25343\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λοετρόν</h1><div class=\"entry-meta\"><span>DGP · ordem 736 na letra λ · nº geral 25343</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ép. = λουτρόν.</p></section></article>\n<article id=\"entry-dgp-25344\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λοετροχόος</h1><div class=\"entry-meta\"><span>DGP · ordem 737 na letra λ · nº geral 25344</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ép. = λουτροχόος.</p></section></article>\n<article id=\"entry-dgp-25345\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λοέω</h1><div class=\"entry-meta\"><span>DGP · ordem 738 na letra λ · nº geral 25345</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(impf. λοέον, aor. part. λοέσσας, inf. λοέσσαι; méd. fut. λοέσσομαι, aor. 3ª sing. λοέσσατο, part. λοεσσάμενος) ép. = λούω.</p></section></article>\n<article id=\"entry-dgp-25346\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λοιβεῖον, ου (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 739 na letra λ · nº geral 25346</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">taça para as libações. 〈λοιβή〉</p></section></article>\n<article id=\"entry-dgp-25347\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λοιβή, ῆς (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 740 na letra λ · nº geral 25347</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 ação de derramar ou de espalhar 2 efeito de derramar; o derramar-se 3 libação 4 água que escoa.</p></section></article>\n<article id=\"entry-dgp-25348\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λοίγιος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 741 na letra λ · nº geral 25348</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">pernicioso; funesto; letal. 〈λοιγός〉</p></section></article>\n<article id=\"entry-dgp-25349\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λοιγός, οῦ (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 742 na letra λ · nº geral 25349</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">flagelo; ruína; destruição; morte.</p></section></article>\n<article id=\"entry-dgp-25350\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λοιδορέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 743 na letra λ · nº geral 25350</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 insultar; injuriar; repreender duramente alguém, ac. ou dat., por algo, ac. ou εἰς e ac.: [τὴν τύχην] τυφλήν λοιδοροῦμεν plut. repreendemos a fortuna por ser cega, ἐγὼ δ’ ἐμαυτὸν πόλλ’ ἐλοιδόρησα δή eur. eu a mim própria dirigi muitas censuras, ἤρξαντο τὸν Ἀσδρούβαν λοιδορεῖν εἰς ἐπιορκίαν pol. começaram a dizer insultos a Asdrúbal em relação ao perjúrio ♦ méd. (aor. ἐλοιδορησάμην e ἐλοιδορήθην) 2 dirigir censuras ofensivas a alguém, dat. ou πρός e ac., por algo, gen. ou περί e gen. ou ἐπί e dat.: πάντα τὰ αἰσχρὰ λοιδορέονται, ὅτι σφέας καίων ἐπιτρίβει her. proferem todas as censuras feias, porque ele [o sol] arde e os consome. 〈λοίδορος〉</p></section></article>\n<article id=\"entry-dgp-25351\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λοιδόρημα, ατος (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 744 na letra λ · nº geral 25351</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">censura ofensiva; ofensa; injúria: λοιδ. ποιεῖσθαι τινα plut. ultrajar alguém. 〈λοιδορέω〉</p></section></article>\n<article id=\"entry-dgp-25352\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λοιδορία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 745 na letra λ · nº geral 25352</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">censura ofensiva; injúria. 〈λοίδορος〉</p></section></article>\n<article id=\"entry-dgp-25353\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λοίδορος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 746 na letra λ · nº geral 25353</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 injurioso; ultrajante ♦ ὁ λοίδορος 2 insultador; ultrajador ♦ τὸ λοίδορον 3 insulto; ultraje.</p></section></article>\n<article id=\"entry-dgp-25354\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λοιμός, οῦ (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 747 na letra λ · nº geral 25354</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 flagelo contagioso; peste; pestilência 2 peste; praga; ameaça pública (pessoa) ♦ adj. 3 funesto (pessoa).</p></section></article>\n<article id=\"entry-dgp-25355\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λοιμώδης, ης, ες</h1><div class=\"entry-meta\"><span>DGP · ordem 748 na letra λ · nº geral 25355</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">pestilento; contagioso. 〈λοιμός, -ωδης〉</p></section></article>\n<article id=\"entry-dgp-25356\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λοιμώσσω,</h1><div class=\"entry-meta\"><span>DGP · ordem 749 na letra λ · nº geral 25356</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">át. -ώττω ser atingido pela peste. 〈λοιμός〉</p></section></article>\n<article id=\"entry-dgp-25357\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λοιπασμός, οῦ (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 750 na letra λ · nº geral 25357</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">saldo de impostos, de contribuições. 〈λοιπός〉</p></section></article>\n<article id=\"entry-dgp-25358\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λοιπός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 751 na letra λ · nº geral 25358</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 que resta; restante; sobra: αἱ λοιπαὶ τῶν νεῶν tuc. o resto dos navios, τὴν λοιπὴν ὁδὸν πορευσόμεθα xen. percorreremos o resto do caminho, λοιπὸν δὴ ἀκόσμητον ἔτι αὐτῷ ἦν τὸ ἀνθρώπων γένος plat. ainda lhe sobrava sem adornos a raça humana, ὃ δὲ λοιπόν ésql. o que resta 2 λοιπόν ou τὸ λοιπόν (ἐστι) com inf., falta; resta: τὸ λοιπὸν ἤδη ἡμῖν ἐστι σκέψασθαι plat. resta-nos, ainda, examinar, λοιπὸν οὖν ἐστὶν οὐδὲν ἄλλο πλὴν ἐπανελθεῖν isócr. só resta então voltar, τί λοιπὸν ἔσται ἤν; isócr. que faltará dizer se? 3 remanescente; futuro (tempo): ὁ λοιπὸς χρόνος át. o futuro, τοῦ λοιποῦ χρόνου sóf., ἐκ τοῦ λοιποῦ xen., τὸν λοιπὸν χρόνον sóf. no futuro, de hoje em diante, doravante ♦ οἱ λοιποί 4 os descendentes; a posteridade ♦ τὸ λοιπόν ou τὰ λοιπά át. 5 o resto: τὸ λοιπὸν τῆς ἡμέρας xen. o resto do dia, καὶ τὰ λοιπά = lat. et coetera, e outros ♦ λοιπόν e τὸ λοιπόν adv. 6 ainda: καθεύδετε τὸ λοιπὸν καὶ ἀναπαύεσθε· ἰδοὺ ἤγγικεν ἡ ὥρα n.t. ainda dormis e repousais! eis que é chegada a hora.</p></section></article>\n<article id=\"entry-dgp-25359\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λοισθήϊος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 752 na letra λ · nº geral 25359</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 do último que chega ♦ τὰ λοισθήϊα 2 prêmio para o que chega por último na corrida. 〈λοῖσθος〉</p></section></article>\n<article id=\"entry-dgp-25360\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λοίσθιος, ος</h1><div class=\"entry-meta\"><span>DGP · ordem 753 na letra λ · nº geral 25360</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">e α, ον 1 último; extremo: τὸ πάντων λοίσ­θιον κακόν eur. o último, i.e., o mais terrível de todos os males ♦ λοίσθιον adv. 2 por fim; enfim. 〈λοῖσθος〉</p></section></article>\n<article id=\"entry-dgp-25361\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λοῖσθος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 754 na letra λ · nº geral 25361</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">extremo; último; derradeiro.</p></section></article>\n<article id=\"entry-dgp-25362\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Λοκρικός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 755 na letra λ · nº geral 25362</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">da Lócrida. 〈Λοκρός〉</p></section></article>\n<article id=\"entry-dgp-25363\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Λοκρίς, ίδος</h1><div class=\"entry-meta\"><span>DGP · ordem 756 na letra λ · nº geral 25363</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fem.) 1 da Lócrida; locrense ♦ ἡ Λοκρίς 2 a Lócrida. 〈Λοκρός〉</p></section></article>\n<article id=\"entry-dgp-25364\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Λοκρός, ά, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 757 na letra λ · nº geral 25364</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 da Lócrida ♦ οἱ Λοκροί 2 os locrenses.</p></section></article>\n<article id=\"entry-dgp-25365\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Λοξίας, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 758 na letra λ · nº geral 25365</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">o Oblíquo, epít. de Apolo, por causa do sentido ambíguo de seus oráculos ou da marcha oblíqua do sol. 〈λοξός〉</p></section></article>\n<article id=\"entry-dgp-25366\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λοξοπορέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 759 na letra λ · nº geral 25366</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">andar obliquamente, tortuosamente. 〈λο­ξός, πόρος〉</p></section></article>\n<article id=\"entry-dgp-25367\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λοξός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 760 na letra λ · nº geral 25367</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 inclinado para um lado; oblíquo: τῶν ἀστέρων λοξὴ γίνεται φορά artt. o movimento dos astros é oblíquo, λοξὸν ὄμμα olhar atravessado, i.e., desafiante, zombeteiro, dissimulado, λοξὰ βλέπειν teócr. olhar de esguelha 2 ambíguo; equívoco; obscuro: λοξοὺς χρησμοὺς συγγράφων luc. escrevendo oráculos ambíguos, λοξὰ ἀποκρινόμενος luc. dando uma resposta ambígua.</p></section></article>\n<article id=\"entry-dgp-25368\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λοξότης, ητος (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 761 na letra λ · nº geral 25368</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 direção oblíqua 2 ambigüidade. 〈λοξός〉</p></section></article>\n<article id=\"entry-dgp-25369\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λοξῶς</h1><div class=\"entry-meta\"><span>DGP · ordem 762 na letra λ · nº geral 25369</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. 1 obliquamente 2 de esguelha 3 de modo ambíguo.</p></section></article>\n<article id=\"entry-dgp-25370\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λόξωσις, εως (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 763 na letra λ · nº geral 25370</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">direção oblíqua; obliqüidade (de eclíptica). 〈λοξός〉</p></section></article>\n<article id=\"entry-dgp-25371\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λοπάδιον, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 764 na letra λ · nº geral 25371</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">prato pequeno. 〈λοπάς〉</p></section></article>\n<article id=\"entry-dgp-25372\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λοπάς, άδος (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 765 na letra λ · nº geral 25372</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 prato de barro; terrina; travessa 2 panela de barro; caçarola 3 alimento; iguaria 4 urna funerária 5 doença da casca da oliveira. 〈λέπω〉</p></section></article>\n<article id=\"entry-dgp-25373\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λοπός, οῦ (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 766 na letra λ · nº geral 25373</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 casca (de fruto) 2 pele de animal 3 pele que escama por causa de doença. 〈λέπω〉</p></section></article>\n<article id=\"entry-dgp-25374\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Λουκᾶς, ᾶ (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 767 na letra λ · nº geral 25374</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">bíbl. Lucas, um dos quatro evangelistas.</p></section></article>\n<article id=\"entry-dgp-25375\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Λούκιος, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 768 na letra λ · nº geral 25375</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">Lúcio, n. de h. [lat.]</p></section></article>\n<article id=\"entry-dgp-25376\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λούμενος</h1><div class=\"entry-meta\"><span>DGP · ordem 769 na letra λ · nº geral 25376</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">part. pres. pas. contr., λοῦνται 3ª pl. pres. ind. pas. contr., λούσαντο 3ª pl. aor. méd. poét., λοῦσθαι inf. pres. pas. contr., de λούω.</p></section></article>\n<article id=\"entry-dgp-25377\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λούστης, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 770 na letra λ · nº geral 25377</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">aquele que gosta de tomar banho. 〈λούω〉</p></section></article>\n<article id=\"entry-dgp-25378\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λουτιάω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 771 na letra λ · nº geral 25378</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ter vontade de banhar-se. 〈λούω〉</p></section></article>\n<article id=\"entry-dgp-25379\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λούτριον, ου (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 772 na letra λ · nº geral 25379</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">água de banho já usada. 〈λουτρόν〉</p></section></article>\n<article id=\"entry-dgp-25380\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λουτροδάϊκτος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 773 na letra λ · nº geral 25380</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">morto no banho. 〈λουτρόν, δαΐζω〉</p></section></article>\n<article id=\"entry-dgp-25381\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λουτρόν, οῦ (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 774 na letra λ · nº geral 25381</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 lugar onde se toma banho; banheiro 2 água de banho 3 ação de banhar-se: λουτροῖς χρῆσθαι xen. tomar banhos 4 água lustral para as purificações 5 purificação 6 crist. água batismal 7 crist. batismo. 〈λούω〉</p></section></article>\n<article id=\"entry-dgp-25382\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λουτροχόος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 775 na letra λ · nº geral 25382</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 que despeja a água do banho 2 usado no preparo do banho: λ. τρίπους hom. recipiente em tripé usado para preparar a água do banho ♦ ὁ, ἡ λουτροχόος 3 servo ou serva que prepara o banho. 〈λουτρόν, χέω〉</p></section></article>\n<article id=\"entry-dgp-25383\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λουτρών, ῶνος (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 776 na letra λ · nº geral 25383</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">quarto de banho; banheiro. 〈λούω〉</p></section></article>\n<article id=\"entry-dgp-25384\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λούω</h1><div class=\"entry-meta\"><span>DGP · ordem 777 na letra λ · nº geral 25384</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(impf. ἔλουον, fut. λούσω, aor. ἔλουσα, perf. desus.; pas. aor. ἐλούθην e ἐλούσθην) 1 lavar o corpo; dar banho em, ac.; fazer tomar banho: λ. τινὰ ἁγνὸν λουτρόν sóf. banhar alguém com água lustral 2 lavar: λοῦσαι νεκρόν hom. lavar um morto 3 crist. mergulhar na água; batizar 4 bíbl. purificar ♦ méd. 5 banhar-se: λούεσθαι ποταμοῖο ou ποταμοῖο ῥοῇσιν ou ἐν ποταμῷ hom. banhar-se num rio, na corrente de um rio, λ. ἀπὸ κρήνης her. banhar-se numa fonte 6 molhar-se 7 bíbl. purificar-se 8 crist. batizar-se.</p></section></article>\n<article id=\"entry-dgp-25385\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λοφάω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 778 na letra λ · nº geral 25385</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 ter um topete 2 ter um penacho. 〈λόφος〉</p></section></article>\n<article id=\"entry-dgp-25386\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λοφηφόρος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 779 na letra λ · nº geral 25386</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">que leva uma crista ou um penacho. 〈λόφος, φέρω〉</p></section></article>\n<article id=\"entry-dgp-25387\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λοφιά, ᾶς (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 780 na letra λ · nº geral 25387</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 pescoço com crina de pêlos longos 2 pêlos longos; penacho; crina; cerdas 3 nadadeira dorsal (do peixe) 4 dorso de animal 5 colina. 〈λόφος〉</p></section></article>\n<article id=\"entry-dgp-25388\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λοφίδιον, ου (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 781 na letra λ · nº geral 25388</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">colina pequena; outeiro. 〈λόφος〉</p></section></article>\n<article id=\"entry-dgp-25389\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λοφιή</h1><div class=\"entry-meta\"><span>DGP · ordem 782 na letra λ · nº geral 25389</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">jôn. = λοφιά.</p></section></article>\n<article id=\"entry-dgp-25390\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λόφος, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 783 na letra λ · nº geral 25390</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 pescoço de animal: ὑπὸ ζυγῷ λόφον ἔχειν sóf. ter o pescoço sob o jugo, i.e., obedecer docilmente 2 crista de galo 3 crina de cavalo 4 topete de pássaro; penacho 5 tufo de cabelos salientes no alto da cabeça; topete 6 nadadeira dorsal 7 cume de uma colina; colina. 〈λέπω〉</p></section></article>\n<article id=\"entry-dgp-25391\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λοχαγέτης, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 784 na letra λ · nº geral 25391</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">λοχαγός.</p></section></article>\n<article id=\"entry-dgp-25392\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λοχαγέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 785 na letra λ · nº geral 25392</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">comandar uma companhia. 〈λοχαγός〉</p></section></article>\n<article id=\"entry-dgp-25393\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λοχαγία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 786 na letra λ · nº geral 25393</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">comando de uma companhia. 〈λοχαγός〉</p></section></article>\n<article id=\"entry-dgp-25394\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λοχαγός, οῦ (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 787 na letra λ · nº geral 25394</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 comandante de tropa armada 2 em Atenas, comandante de companhia de cem homens 3 em Esparta, comandante de um λόχος, quarta parte de uma μόρα 4 em Roma, centurião 5 entre os persas, comandante de vinte e quatro homens. 〈λόχος, ἄγω〉</p></section></article>\n<article id=\"entry-dgp-25395\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λοχάω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 788 na letra λ · nº geral 25395</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. λοχήσω, aor. ἐλόχησα, perf. desus.) 1 preparar armadilhas a alguém, ac. 2 surpreender alguém, ac. 3 ocupar ou interceptar por uma emboscada: λ. ὁδόν her. interceptar por meio de emboscada um caminho ♦ méd. (fut. λοχηθήσομαι, aor. ἐλοχησάμην, perf. λελό­χημαι) 4 pôr-se em emboscada, de tocaia 5 preparar ciladas a alguém, ac. 〈λόχος〉</p></section></article>\n<article id=\"entry-dgp-25396\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λοχεία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 789 na letra λ · nº geral 25396</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 parto 2 postura de ovos, ref. a pássaros 3 fruto do parto. 〈λοχεύω〉</p></section></article>\n<article id=\"entry-dgp-25397\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λοχεῖος, α</h1><div class=\"entry-meta\"><span>DGP · ordem 790 na letra λ · nº geral 25397</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">e ος, ον 1 referente ao parto ♦ ἡ Λοχεία 2 aquela que preside os partos, epít. de Ártemis ♦ τὰ λοχεῖα 3 lugar do parto. 〈λόχος〉</p></section></article>\n<article id=\"entry-dgp-25398\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λόχευμα, ατος (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 791 na letra λ · nº geral 25398</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 parto 2 fruto do parto; filho. 〈λοχεύω〉</p></section></article>\n<article id=\"entry-dgp-25399\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λοχεύω</h1><div class=\"entry-meta\"><span>DGP · ordem 792 na letra λ · nº geral 25399</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 (mãe) pôr no mundo; parir 2 (pais) engendrar; gerar 3 compor; produzir (cantos) 4 (parteira) assistir uma mulher, ac., no parto; fazer dar à luz ♦ méd. 5 (mãe) dar à luz; parir 6 (pai) engendrar. 〈λόχος〉</p></section></article>\n<article id=\"entry-dgp-25400\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λοχηγέω</h1><div class=\"entry-meta\"><span>DGP · ordem 793 na letra λ · nº geral 25400</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">jôn. = λοχαγέω.</p></section></article>\n";
